source('mp10_immune_endothelial_mechanisms_v1/scripts/common.R');b<-qread(file.path(B,'objects/pseudobulk.qs'),nthreads=1);st<-rd('model_status.tsv');mem<-rd('model_membership.tsv.gz');out<-list();summ<-list()
for(id in st[status=='completed',model_id]){d<-rd(paste0('de/',id,'.tsv.gz'));ids<-mem[model_id==id,profile_id];total<-Matrix::rowSums(b$counts[,ids,drop=FALSE]);excluded<-setdiff(b$feature_universe,d$gene);ix<-match(excluded,b$feature_universe);out[[id]]<-data.table(model_id=id,gene=excluded,reason=ifelse(total[ix]==0,'observed_zero_across_model_profiles','filterByExpr_not_passed'),total_UMI_across_model_profiles=total[ix]);summ[[id]]<-data.table(model_id=id,n_features=length(b$feature_universe),n_tested=nrow(d),n_excluded=length(excluded),n_observed_zero=sum(total==0));stopifnot(!any(d$gene%in%excluded),length(union(d$gene,excluded))==length(b$feature_universe))};put(rbindlist(out),'de_gene_filter_exclusions.tsv.gz');put(rbindlist(summ),'de_gene_domain_summary.tsv');cat('GENE DOMAINS COMPLETE\n')
